"""Generate firmware UI limits from the shared device and card definitions."""

from __future__ import annotations

import json
import re

from device_profiles import load_device_profiles, web_config
from product_schema import load_card_contract


def profile_flag(slug: str) -> str:
    return "ESPCONTROL_UI_PROFILE_" + re.sub(r"[^A-Za-z0-9]", "_", slug).upper()


def render_header() -> str:
    profiles = list(load_device_profiles().values())
    cards = load_card_contract()["cards"]
    lines = [
        "#pragma once",
        "",
        "// Generated by scripts/generate_device_slots.py. Do not edit.",
        "// Source: devices/manifest.json and the Product Model card contract.",
        "namespace espcontrol {",
        "",
    ]
    # Share identical support tables rather than repeating them per device.
    support_tables: dict[tuple[str, ...], int] = {}
    profile_tables = []
    for profile in profiles:
        disabled = set(web_config(profile).get("disabledCardTypes", []))
        supported = tuple(key for key in cards if key not in disabled)
        if supported not in support_tables:
            table = len(support_tables)
            support_tables[supported] = table
            lines.append(f"inline constexpr DeviceCardTypeSupport DEVICE_UI_CARD_TYPES_{table}[] = {{")
            for key in supported:
                allowed = str(bool(cards[key].get("allowInSubpage"))).lower()
                lines.append(f"    {{{json.dumps(key)}, {allowed}}},")
            lines.extend(["};", ""])
        profile_tables.append(support_tables[supported])

    lines.append("inline constexpr DeviceUiLimits DEVICE_UI_PROFILES[] = {")
    for profile, table in zip(profiles, profile_tables):
        slots = profile["slots"]
        layout = profile["layout"]
        chunks = profile["firmware"]["package"].get("subpageConfigChunks", 8)
        subpages = slots if "subpage" not in web_config(profile).get("disabledCardTypes", []) else 0
        values = [layout["cols"], layout["rows"], slots, subpages,
                  slots - 1, 1, profile["capabilities"]["imageSlots"], chunks, 255]
        lines.append(f"    {{{json.dumps(profile['slug'])}, " + ", ".join(map(str, values)) +
                     f", DEVICE_UI_CARD_TYPES_{table}, " +
                     f"sizeof(DEVICE_UI_CARD_TYPES_{table}) / sizeof(DeviceCardTypeSupport)" + "},")
    lines.extend(["};", "", "}  // namespace espcontrol", ""])

    flags = [profile_flag(profile["slug"]) for profile in profiles]
    lines.extend(["#if (" + " + ".join(f"defined({flag})" for flag in flags) + ") > 1",
                  '#error "Select only one EspControl UI device profile"', "#endif", ""])
    for index, (profile, flag) in enumerate(zip(profiles, flags)):
        lines.extend([
            ("#if" if index == 0 else "#elif") + f" defined({flag})",
            f"#define ESPCONTROL_DEVICE_UI_SLOT_COUNT {profile['slots']}",
            "namespace espcontrol {",
            f"inline constexpr DeviceUiLimits DEVICE_UI_LIMITS = DEVICE_UI_PROFILES[{index}];",
            "}  // namespace espcontrol",
        ])
    lines.extend(["#endif", ""])
    return "\n".join(lines)
